// ============================================================================
//  sfap_tables.h  --  GENERATED constant tables for sfap_pi (N = 64)
//  Twiddles W_64^n = exp(-j 2 pi n / 64), n = 0..31, signed Q1.16 (1.0 = 65536)
//  Window  w[n] = sin(pi n / 64), n = 0..63 (square root of the periodic Hann),
//          unsigned Q16. w[n]^2 + w[n+32]^2 = 1, so analysis x synthesis with
//          50 % overlap reconstructs the input exactly when the weights are 0.
//  Regenerate with Source/HLS/sfap_pi/gen_tables.py if SFAP_LOG2N changes.
// ============================================================================
